import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.ChTAMbUy.js";const p=JSON.parse('{"title":"LLM Serving","description":"","frontmatter":{},"headers":[],"relativePath":"1.9/agentops/llm_serving.md","filePath":"versions/1.9/agentops/llm_serving.md","lastUpdated":1791569256000}'),n={name:"1.9/agentops/llm_serving.md"};function r(i,e,l,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="llm-serving" tabindex="-1">LLM Serving <a class="header-anchor" href="#llm-serving" aria-label="Permalink to &quot;LLM Serving&quot;">​</a></h1><p>LLM Serving deploys self-hosted models as OpenAI-compatible inference endpoints on KServe. It supports text generation, embedding, reranking, text-to-speech, and speech-to-text models. Use it when you want to host a model in the cluster instead of calling an external provider such as OpenAI, Anthropic, or Gemini.</p><div class="info custom-block"><p class="custom-block-title">Upstream references</p><p>LLM Serving builds on:</p><ul><li><a href="https://kserve.github.io/website/" target="_blank" rel="noreferrer">KServe</a> for the serving control plane and OpenAI-compatible protocol</li><li><a href="https://docs.vllm.ai/" target="_blank" rel="noreferrer">vLLM</a> and <a href="https://kserve.github.io/website/latest/modelserving/v1beta1/llm/huggingface/" target="_blank" rel="noreferrer">KServe&#39;s HuggingFace runtime</a> for text generation and embeddings</li><li><a href="https://huggingface.co/docs/text-embeddings-inference" target="_blank" rel="noreferrer">Hugging Face Text Embeddings Inference (TEI)</a> for CPU-optimized embeddings</li><li><a href="https://github.com/SYSTRAN/faster-whisper" target="_blank" rel="noreferrer">faster-whisper</a> for CPU speech-to-text</li></ul></div><p>LLM Serving is an AgentOps capability. For classic model serving with scikit-learn, PyTorch, and similar predictors, see <a href="./../mlops/model_serving.html">Model Serving</a>. Both features use KServe, but they provide different deployment forms and endpoints.</p><h2 id="when-to-use-llm-serving" tabindex="-1">When to Use LLM Serving <a class="header-anchor" href="#when-to-use-llm-serving" aria-label="Permalink to &quot;When to Use LLM Serving&quot;">​</a></h2><ul><li>Host an open-weight model (Llama, Mistral, Qwen, Gemma, and similar) in-cluster instead of calling an external API.</li><li>Serve embedding or reranking models for retrieval workloads.</li><li>Serve text-to-speech or speech-to-text models.</li><li>Provide an in-cluster model for a kagent <a href="./agents.html">Agent</a> via an <strong>Internal</strong> Model Configuration, with or without tool calling.</li><li>Keep model traffic and data inside the cluster instead of sending it to an external provider.</li></ul><p>If you only need OpenAI, Anthropic, or Gemini, create a Model Configuration directly instead. See <a href="./agents.html#_2-choose-or-create-a-model-configuration">Agents: Choose or Create a Model Configuration</a>.</p><h2 id="deploy-a-model" tabindex="-1">Deploy a Model <a class="header-anchor" href="#deploy-a-model" aria-label="Permalink to &quot;Deploy a Model&quot;">​</a></h2><p>Open <strong>LLM Serving</strong> in the sidebar. The page lists the models deployed in the selected workspace.</p><p>Click <strong>Deploy Model</strong> and choose a preset, or select <strong>Deploy Custom Model</strong> to configure the deployment from scratch. Presets provide curated defaults and can be searched or filtered by GPU count, task type, and verification status. Both paths open the same form:</p><ul><li><strong>Deployment Name</strong>: unique name in the workspace.</li><li><strong>Model Type</strong>: Text Generation, Embedding, Reranking, Text to Speech, or Speech to Text. Typing a HuggingFace-style model ID (<code>org/model</code>) auto-detects the type.</li><li><strong>Model ID</strong>: a HuggingFace model ID, for example <code>meta-llama/Llama-2-7b-chat-hf</code>.</li><li><strong>Model Weights Source</strong>: <strong>Download from Hugging Face</strong> fetches the weights when the model starts. <strong>Use cached weights (recommended)</strong> appears when a <a href="#cache-model-weights">cache</a> for the model is ready. <strong>Advanced: use custom S3/PVC location</strong> takes an <code>s3://</code> or <code>pvc://</code> location that you manage yourself.</li><li><strong>Runtime</strong>: filtered to the runtimes that support the selected type.</li></ul><table tabindex="0"><thead><tr><th>Model type</th><th>Available runtimes</th></tr></thead><tbody><tr><td>Text Generation</td><td>HuggingFace (recommended), vLLM</td></tr><tr><td>Embedding</td><td>HuggingFace, TEI (CPU-optimized), vLLM</td></tr><tr><td>Reranking</td><td>HuggingFace, vLLM</td></tr><tr><td>Text to Speech</td><td>vLLM Omni</td></tr><tr><td>Speech to Text</td><td>vLLM Omni, faster-whisper (CPU, no GPU required)</td></tr></tbody></table><p>vLLM and vLLM Omni require a custom ClusterServingRuntime.</p><p>If the model is gated on HuggingFace, the form warns you before deploying: accept the license on huggingface.co, create an access token, and store it as a Kubernetes Secret named <code>storage-config</code> with key <code>HF_TOKEN</code> in the workspace (see <a href="./../platform/kubernetes.html#kubernetes-secrets">Kubernetes Secrets</a>). Deployment fails without it.</p><p>Select <strong>Or edit YAML manifest directly</strong> if the form does not cover a setting you need, such as extra container arguments.</p><h2 id="cache-model-weights" tabindex="-1">Cache Model Weights <a class="header-anchor" href="#cache-model-weights" aria-label="Permalink to &quot;Cache Model Weights&quot;">​</a></h2><p>Without a cache, every model pod downloads its weights from Hugging Face when it starts. For large models, this is slow and depends on Hugging Face being reachable, and it repeats for every redeploy and every new replica. Managed model caching downloads a preset&#39;s weights once into storage in the cluster. Later deployments load them from there.</p><p>Caching is available for curated presets with a Hugging Face model. For custom models, store the weights yourself and use <strong>Advanced: use custom S3/PVC location</strong>.</p><h3 id="choose-a-destination" tabindex="-1">Choose a Destination <a class="header-anchor" href="#choose-a-destination" aria-label="Permalink to &quot;Choose a Destination&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Destination</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>Workspace S3</strong> (default)</td><td>Stores the weights in the workspace bucket under <code>model-cache/</code>, by default <code>s3://&lt;workspace&gt;-data/model-cache/...</code>. Each model pod still copies the weights at startup, but from in-cluster storage instead of Hugging Face. Any number of replicas can use the same cache.</td></tr><tr><td><strong>Dedicated PVC</strong></td><td>Available only when an administrator has enabled it. See <a href="./../admin/storage.html#model-cache-pvcs">Model Cache PVCs</a>. Creates a new PersistentVolumeClaim that holds only this cache. KServe mounts the claim read-only into the model pods instead of copying the weights.</td></tr></tbody></table><p>For a PVC cache, the access mode decides where replicas can run:</p><ul><li><code>ReadWriteOnce</code>: the claim attaches to one node at a time. All replicas must run on that node; a replica scheduled on another node cannot start.</li><li><code>ReadWriteOncePod</code>: only one pod can use the claim, so the model is limited to one replica.</li><li><code>ReadWriteMany</code>: replicas can run on several nodes, if the StorageClass supports it.</li></ul><p>If a model needs replicas on several nodes and no <code>ReadWriteMany</code> option is offered, use workspace S3.</p><h3 id="cache-a-preset" tabindex="-1">Cache a Preset <a class="header-anchor" href="#cache-a-preset" aria-label="Permalink to &quot;Cache a Preset&quot;">​</a></h3><ol><li>Open <strong>LLM Serving</strong>, select <strong>Deploy Model</strong>, and find the preset. Each cacheable preset card shows its cache status.</li><li>Select <strong>Cache this model</strong>. The dialog shows the model, the Hugging Face revision it resolved to, and the file format.</li><li>If an administrator has enabled PVC caches, the dialog shows <strong>Storage destination</strong>. Choose <strong>Workspace S3</strong> or <strong>Dedicated PVC</strong>. For a PVC, select the StorageClass, access mode, and claim size within the displayed limits. Otherwise, the cache goes to workspace S3.</li><li>For a gated model, the dialog shows a <strong>Hugging Face credential</strong> field. Select the Secret that holds your token. See <a href="#gated-models">Gated Models</a>.</li><li>Select <strong>Start caching</strong>.</li></ol><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/agentops/llm-serving/model-cache-dialog-pvc.png" alt="Cache dialog with Dedicated PVC selected, showing StorageClass, access mode, and claim size" loading="lazy"></p><p>The download runs as a Kubernetes Job in the workspace.</p><h4 id="gated-models" tabindex="-1">Gated Models <a class="header-anchor" href="#gated-models" aria-label="Permalink to &quot;Gated Models&quot;">​</a></h4><p>Some Hugging Face models, such as Llama and Gemma, are gated: you must accept the model&#39;s license on huggingface.co, and downloads need an access token. Public models need no token, and the dialog does not show the credential field for them.</p><p>To cache a gated model, store your token in a workspace Secret with the key <code>HF_TOKEN</code> and the label <code>prokube.ai/credential-type=huggingface</code>. The credential field lists only Secrets with this label, so the <code>storage-config</code> Secret that direct deployments from Hugging Face use does not appear unless you label it. Create the Secret with <code>kubectl</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hf-token</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">workspac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-literal=HF_TOKEN=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">token</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> label</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hf-token</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">workspac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prokube.ai/credential-type=huggingface</span></span></code></pre></div><p>Deployments from a ready cache do not need the token.</p><h3 id="monitor-a-cache" tabindex="-1">Monitor a Cache <a class="header-anchor" href="#monitor-a-cache" aria-label="Permalink to &quot;Monitor a Cache&quot;">​</a></h3><p>The status on the preset card shows the state of the cache:</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/agentops/llm-serving/model-cache-preset-status.png" alt="Preset cards with a Cached status and estimated size, and Not cached presets with a Cache this model button" loading="lazy"></p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Caching</strong></td><td>The download Job is running.</td></tr><tr><td><strong>Cached</strong></td><td>The cache is ready. The card shows its estimated size.</td></tr><tr><td><strong>Cached revision is stale</strong></td><td>The preset now points to a newer Hugging Face revision. Models already deployed from the old cache keep running on it, but new deployments cannot use it. Select <strong>Cache this model</strong> to cache the current revision.</td></tr><tr><td><strong>Cache failed</strong></td><td>The download failed. Open the cache details to read the logs.</td></tr></tbody></table><p>For <strong>Caching</strong>, <strong>Cached</strong>, and <strong>Cache failed</strong>, select the status to open <strong>Model cache details</strong>. It shows the destination and revision, and offers <strong>View logs</strong>, <strong>Cancel</strong> for a running download, and <strong>Copy URI</strong> for a ready cache.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/agentops/llm-serving/model-cache-details.png" alt="Model cache details for a ready S3 cache with Copy URI, Delete cached weights, and Deploy from cache actions" loading="lazy"></p><h3 id="deploy-from-a-cache" tabindex="-1">Deploy from a Cache <a class="header-anchor" href="#deploy-from-a-cache" aria-label="Permalink to &quot;Deploy from a Cache&quot;">​</a></h3><p>Select <strong>Deploy from cache</strong> in the cache details. You can also open the preset as usual: when a ready cache exists, <strong>Model Weights Source</strong> defaults to <strong>Use cached weights (recommended)</strong>. If the model has more than one ready cache, for example one in S3 and one on a PVC, select the one to use.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/agentops/llm-serving/model-weights-source-cached.png" alt="Model Weights Source in the deploy form with a PVC cache selected under Use cached weights" loading="lazy"></p><h3 id="delete-cached-weights" tabindex="-1">Delete Cached Weights <a class="header-anchor" href="#delete-cached-weights" aria-label="Permalink to &quot;Delete Cached Weights&quot;">​</a></h3><p>Deleting a model does not delete its cached weights, so the next deployment can reuse them. To free the storage, open the cache details, select <strong>Delete cached weights</strong>, and type the cache ID to confirm.</p><ul><li>Cleanup is blocked while a model still uses the cache. Delete those models or deploy them from another source first.</li><li>For a PVC cache, the whole claim is deleted. Whether the underlying volume and its data are removed depends on the StorageClass reclaim policy.</li><li>A failed or cancelled cache keeps its partial data and cannot be reused or overwritten. Delete its cached weights before you cache the model again.</li></ul><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/agentops/llm-serving/model-cache-cleanup-blocked.png" alt="Delete cached weights dialog blocked because a deployed model still uses the cache" loading="lazy"></p><p>For an S3 cache, cleanup runs as a Kubernetes Job in the workspace, and the dialog shows the Job status and logs. For a PVC cache, the dialog shows the status of the claim deletion.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/agentops/llm-serving/model-cache-cleanup-logs.png" alt="Cleanup in progress with the cleanup Job status and logs" loading="lazy"></p><p>If cleanup fails, some objects may already be deleted. For a failed S3 cleanup, remove the remaining objects under the cache&#39;s prefix, then confirm manual cleanup in the dialog. If the dialog shows that the cleanup state is unknown, ask an administrator to check the cleanup Job and the cache record.</p><h2 id="advanced-configuration" tabindex="-1">Advanced Configuration <a class="header-anchor" href="#advanced-configuration" aria-label="Permalink to &quot;Advanced Configuration&quot;">​</a></h2><p>The <strong>Advanced Configuration</strong> section is collapsed by default. It covers:</p><ul><li><a href="https://kserve.github.io/website/docs/concepts/architecture/control-plane" target="_blank" rel="noreferrer"><strong>Deployment Mode</strong></a>: <strong>Serverless (Knative)</strong> is the default and supports scale-to-zero. <strong>Raw (also called Standard in newer KServe versions) Deployment</strong> creates a plain Kubernetes Deployment for clusters without Knative or for <a href="https://keda.sh/docs/latest/concepts/scaling-deployments/" target="_blank" rel="noreferrer">KEDA</a> autoscaling. Raw deployments require at least one replica.</li><li><strong>Runtime settings</strong>: vLLM-based runtimes support quantization options such as AWQ, GPTQ, and FP8, and data types such as Float16, BFloat16, and Float32. The HuggingFace runtime uses vLLM internally, so these settings also apply to it.</li><li><strong>Resource Requests</strong>: configure CPU, memory, and GPU count and type. GPU options come from the cluster inventory. If limits are left blank, the CPU limit defaults to twice the request and the memory limit matches the request.</li><li><strong>Auto-Scaling</strong>: configure minimum and maximum replicas, with a maximum of 10. Serverless mode allows a minimum of 0 for scale-to-zero; Raw Deployment requires at least one replica.</li><li><strong>Automatic tool calling</strong>: configure support for agents that use MCP tools. See <a href="#enable-tool-calling-for-agents">Enable Tool Calling for Agents</a>.</li></ul><p>Raw deployments can use <a href="https://kubernetes.io/docs/tasks/run-application/horizontal-pod-autoscale/" target="_blank" rel="noreferrer">HPA</a> for CPU or memory-based scaling, or <a href="https://keda.sh/docs/latest/concepts/scaling-deployments/" target="_blank" rel="noreferrer">KEDA</a> for custom Prometheus metrics such as vLLM token throughput. KEDA requires a PromQL query and a scale threshold calibrated against observed traffic. See <a href="./../mlops/model_serving_autoscaling.html">Serving Autoscaling</a> for the general KEDA pattern in prokube.</p><h2 id="enable-tool-calling-for-agents" tabindex="-1">Enable Tool Calling for Agents <a class="header-anchor" href="#enable-tool-calling-for-agents" aria-label="Permalink to &quot;Enable Tool Calling for Agents&quot;">​</a></h2><p>Not every runtime supports OpenAI-style tool calling. The <strong>Enable automatic tool calling</strong> option appears only for <strong>vLLM</strong> and <strong>HuggingFace</strong> text-generation models. It is not available for TEI, vLLM Omni, faster-whisper, or other model types.</p><p>If you plan to attach MCP tools to a kagent agent that uses this model (an <strong>Internal</strong> Model Configuration), turn this on and select a <strong>Tool-call parser</strong> matching the model&#39;s tool-call format:</p><table tabindex="0"><thead><tr><th>Parser</th><th>Matches</th></tr></thead><tbody><tr><td>Hermes</td><td>Qwen 2.5, QwQ, and Nous Hermes formats</td></tr><tr><td>Qwen3 XML</td><td>Qwen3-Coder tool-call format</td></tr><tr><td>Llama 3 JSON</td><td>Llama models using JSON tool calls</td></tr><tr><td>Pythonic</td><td>Llama models using Python-style tool calls</td></tr><tr><td>Mistral</td><td>Mistral tool-call format</td></tr><tr><td>DeepSeek V3</td><td>DeepSeek V3 format</td></tr><tr><td>DeepSeek V3.1</td><td>DeepSeek V3.1 format</td></tr></tbody></table><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/agentops/llm-serving/automatic-tool-calling.png" alt="LLM deployment form with automatic tool calling and parser selection" loading="lazy"></p><p>This list matches the parsers built into the platform&#39;s currently deployed vLLM runtime and may change as that runtime is upgraded; use YAML editing for a parser or chat template not listed here. Without a matching parser, an agent&#39;s tool calls against this model will not work reliably even though the Model Configuration and deployment are otherwise valid.</p><h2 id="test-a-deployed-model" tabindex="-1">Test a Deployed Model <a class="header-anchor" href="#test-a-deployed-model" aria-label="Permalink to &quot;Test a Deployed Model&quot;">​</a></h2><p>Open a <strong>Ready</strong> model from the list. Text-generation models have a <strong>Chat</strong> tab with a built-in streaming chat tester. Embedding and reranking models have an <strong>API</strong> tab. Audio models have an <strong>API</strong> or <strong>Test</strong> tab, depending on the task. These tabs show the endpoint path and a ready-to-run <code>curl</code> example for the supported operation.</p><p>The <strong>Configuration</strong> tab summarizes the model&#39;s settings and endpoints. For troubleshooting, use the <strong>Metrics</strong>, <strong>Logs</strong>, and <strong>Conditions</strong> tabs. While model weights are downloading, a storage panel shows download progress and errors instead of the usual tabs.</p><h2 id="edit-a-model" tabindex="-1">Edit a Model <a class="header-anchor" href="#edit-a-model" aria-label="Permalink to &quot;Edit a Model&quot;">​</a></h2><p>From the model list or detail page, select <strong>Edit</strong> to change Model Type, Quantization, Data Type, tool-calling settings, resource requests and limits, or auto-scaling. Model ID, runtime, and deployment mode are fixed after creation. To change them, delete and redeploy the model or use the <strong>YAML</strong> tab.</p><h2 id="external-access" tabindex="-1">External Access <a class="header-anchor" href="#external-access" aria-label="Permalink to &quot;External Access&quot;">​</a></h2><p>The endpoints on the model&#39;s <strong>Chat</strong> and <strong>API</strong> tabs are external URLs served through <a href="./../platform/agent_gateway.html">Agent Gateway</a>. External clients, such as SDKs, CI jobs, and applications outside the cluster, call them with an API key scoped to the model. See <a href="./../platform/api_keys.html">API Keys</a>. The URL depends on the model type:</p><table tabindex="0"><thead><tr><th>Model type</th><th>URL pattern</th></tr></thead><tbody><tr><td>Text Generation, Embedding, Reranking</td><td><code>/svc/ai/&lt;workspace&gt;/models/&lt;deployment-name&gt;/v1/...</code></td></tr><tr><td>Text to Speech, Speech to Text</td><td><code>/svc/serving/&lt;workspace&gt;/&lt;deployment-name&gt;/openai/v1/audio/...</code></td></tr></tbody></table><p>Models granted through <a href="./../admin/external_models.html">External Models</a> use the <code>/svc/ai</code> pattern with the route ID chosen in the grant. They are not listed as individual services on the API Keys page, so they need a Bearer-format key with <strong>All external AI models</strong>, <strong>All AI models</strong>, or <strong>Full workspace access</strong>.</p><p>To use a deployed model from a kagent agent instead of an external client, create an <strong>Internal - OpenAI-compatible</strong> Model Configuration and pick this model from the <strong>LLM Serving model</strong> dropdown. See <a href="./agents.html#_2-choose-or-create-a-model-configuration">Agents</a>.</p><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./agents.html">Agents</a></li><li><a href="./agent_gateway.html">Agent Gateway</a></li><li><a href="./../platform/api_keys.html">API Keys</a></li><li><a href="./../mlops/model_serving.html">Model Serving</a></li><li><a href="./../mlops/model_serving_autoscaling.html">Serving Autoscaling</a></li></ul>`,70)])])}const m=t(n,[["render",r]]);export{p as __pageData,m as default};
